    "text": ".resource-steps{display:flex;align-items:center;gap:var(--space-10);padding:var(--space-10) 0;margin:0;list-style:none;font-size:10px;color:var(--muted);flex-wrap:wrap}\n.resource-steps>li{display:flex;align-items:center;gap:var(--space-5)}\n.resource-steps i{width:18px;height:18px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%;font:9px var(--mono);font-style:normal;background:var(--panel)}\n.resource-steps i svg{width:11px;height:11px}\n.resource-steps .done{color:var(--green)}\n.resource-steps .done i{background:var(--green-bg);border-color:transparent}\n.resource-actions{display:flex;align-items:center;gap:var(--space-6);flex-wrap:wrap;padding-top:var(--space-12);border-top:1px solid var(--line);margin-top:var(--space-12)}\n.resource-actions .button{font-size:10px;min-height:36px;padding:var(--space-7) var(--space-10)}\n.resource-ready,.skill-acquisition-state{font-size:10px;color:var(--muted)}\n.skill-acquisition-state{margin:var(--space-12) 0 0;line-height:1.8}\n.skill-state.unavailable{color:var(--muted);background:var(--panel)}\n.skill-card-actions{flex-wrap:wrap}\n.extension-card .extension-card-footer{gap:var(--space-8);flex-wrap:wrap}\n.extension-card .extension-card-footer>span{overflow-wrap:anywhere}\n@media(max-width:700px){.resource-actions .button{min-height:44px;font-size:11px}.resource-steps{gap:var(--space-14);font-size:11px}.skill-card-actions .button{min-height:44px}.skill-acquisition-state{font-size:11px}}\n",
