    "text": "# rpi — a Rust agent runtime + CLI. See README.md and docs/architecture/overview.md.\n[workspace]\nmembers = [\n    \"crates/rpi-telemetry\",\n    \"crates/rpi-ai\",\n    \"crates/rpi-agent\",\n    \"crates/rpi-tools\",\n    \"crates/rpi-harness\",\n    \"crates/rpi-cli\",\n    \"crates/rpi-runtime\",\n    \"crates/rpi-tui\",\n    \"crates/rpi-plugin-sdk\",\n    \"crates/rpi-extensions\",\n    \"examples/minimal\",\n    \"examples/tools\",\n    \"examples/tui\",\n    \"examples/plugin-stub\",\n]\ndefault-members = [\n    \"crates/rpi-agent\",\n    \"crates/rpi-tools\",\n    \"crates/rpi-harness\",\n    \"crates/rpi-cli\",\n]\nresolver = \"2\"\n\n[workspace.package]\nedition = \"2021\"\nrust-version = \"1.78\"\nlicense = \"MIT\"\nrepository = \"https://github.com/bigfish1913/pi-rust\"\nhomepage = \"https://rpi.laofu.online/\"\nversion = \"0.8.4\"\nauthors = [\"BigFish <fuwei201473@gmail.com>\"]\n\n[workspace.dependencies]\n# Async runtime\ntokio = { version = \"1\", features = [\"rt-multi-thread\", \"macros\", \"time\", \"fs\", \"process\", \"sync\", \"io-util\"] }\ntokio-util = { version = \"0.7\", features = [\"rt\"] }\nasync-trait = \"0.1\"\nfutures = \"0.3\"\nfs2 = \"0.4\"\n\n# Serialization / schemas\nserde = { version = \"1\", features = [\"derive\", \"rc\"] }\nserde_json = { version = \"1\", features = [\"preserve_order\", \"raw_value\"] }\nyaml_serde = \"=0.10.2\"\nindexmap = { version = \"2\", features = [\"serde\"] }\nschemars = { version = \"0.8\", features = [\"preserve_order\"] }\njsonschema = \"0.18\"\n\n# HTTP / SSE (used by anthropic provider, M3)\nreqwest = { version = \"0.12\", default-features = false, features = [\"rustls-tls\", \"json\", \"stream\"] }\nbytes = \"1\"\neventsource-stream = \"0.2\"\n\n# Errors / logging\nthiserror = \"1\"\ntracing = \"0.1\"\n\n# Misc\nuuid = { version = \"1\", features = [\"v4\", \"v7\"] }\nrusqlite = { version = \"0.31\", features = [\"bundled\"] }\nbase64 = \"0.22\"\npng = \"0.18\"\nciborium = \"0.2\"\ntempfile = \"3\"\nregex = \"1\"\nsemver = \"1\"\nglobset = \"=0.4.15\"\ndirs = \"5\"\nrpassword = \"7\"\n\n# rpi internal crates (package names and directories both use the `rpi-` prefix).\nrpi-telemetry = { path = \"crates/rpi-telemetry\", version = \"0.8.4\" }\nrpi-ai = { path = \"crates/rpi-ai\", version = \"0.8.4\" }\nrpi-agent = { path = \"crates/rpi-agent\", version = \"0.8.4\" }\nrpi-tools = { path = \"crates/rpi-tools\", version = \"0.8.4\" }\nrpi-harness = { path = \"crates/rpi-harness\", version = \"0.8.4\" }\n\nrpi-runtime = { path = \"crates/rpi-runtime\", version = \"0.8.4\" }\n\nrpi-tui = { path = \"crates/rpi-tui\", version = \"0.8.4\" }\n\nrpi-plugin-sdk = { path = \"crates/rpi-plugin-sdk\", version = \"0.8.4\" }\nrpi-extensions = { path = \"crates/rpi-extensions\", version = \"0.8.4\" }\n\n[profile.release]\nlto = \"thin\"\ncodegen-units = 16\nstrip = \"symbols\"\n",
